"""
Text Adventure Engine

This module implements a simple text adventure engine.

Features:
- Room and item data loaded from JSON config
- Player inventory
- Basic parser for two-word commands (verb + noun)
- Save and load game state using JSON

Commands supported include:
- go [direction]
- look (optionally next word)
- get [item]
- drop [item]
- inventory
- save [filename]
- load [filename]

"""

import json
from typing import Dict, List, Optional


class AdventureGame:
    """Main game class for the text adventure."""

    def __init__(self, config_file: str):
        """Load world data from config file."""
        self.config_file = config_file
        self.rooms = {}  # type: Dict[str, Dict]
        self.items = {}  # type: Dict[str, Dict]
        self.current_room = None  # type: Optional[str]
        self.inventory = []  # type: List[str]
        self.load_config()

    def load_config(self):
        """Load rooms and items from JSON config."""
        with open(self.config_file, 'r') as f:
            data = json.load(f)
        self.rooms = data.get('rooms', {})
        self.items = data.get('items', {})
        # Set starting room to first room defined
        self.current_room = next(iter(self.rooms)) if self.rooms else None

    def describe_current_room(self):
        """Return description of current room including visible items."""
        room = self.rooms.get(self.current_room, {})
        desc = room.get('description', 'You see nothing special.')
        # Items in this room
        item_list = [item['name'] for item in self.items.values() if item['location'] == self.current_room]
        if item_list:
            desc += '\nYou see here: ' + ', '.join(item_list) + '.'
        else:
            desc += '\nThere are no items here.'
        # Exits
        exits = ', '.join(room.get('exits', {}).keys())
        desc += f'\nExits: {exits if exits else "none"}.'
        return desc

    def move(self, direction: str) -> str:
        """Move the player in a direction."""
        current = self.rooms.get(self.current_room, {})
        exits = current.get('exits', {})
        if direction in exits:
            self.current_room = exits[direction]
            return f'You move {direction} to the {self.rooms[self.current_room]["name"]}.\n' + self.describe_current_room()
        else:
            return 'You cannot go that way.'

    def get_item(self, item_name: str) -> str:
        """Pick up an item from the room."""
        # Find item case-insensitive
        found_key = None
        for key, item in self.items.items():
            if item['name'].lower() == item_name.lower() and item['location'] == self.current_room:
                found_key = key
                break
        if found_key:
            self.items[found_key]['location'] = 'inventory'
            self.inventory.append(found_key)
            return f'You picked up the {self.items[found_key]["name"]}.'
        else:
            return f'There is no {item_name} here.'

    def drop_item(self, item_name: str) -> str:
        """Drop an item from inventory into the current room."""
        found_key = None
        for key in self.inventory:
            if self.items[key]['name'].lower() == item_name.lower():
                found_key = key
                break
        if found_key:
            self.items[found_key]['location'] = self.current_room
            self.inventory.remove(found_key)
            return f'You dropped the {self.items[found_key]["name"]}.'
        else:
            return f'You do not have a {item_name}.'

    def inventory_list(self) -> str:
        """List items in inventory."""
        if not self.inventory:
            return 'You are not carrying anything.'
        else:
            item_names = [self.items[key]['name'] for key in self.inventory]
            return 'You are carrying: ' + ', '.join(item_names) + '.'

    def look(self, target: Optional[str] = None) -> str:
        """Look around or at an item."""
        if target is None or target == '':
            return self.describe_current_room()
        # Look for item in inventory or room
        for key, item in self.items.items():
            if item['name'].lower() == target.lower():
                if item['location'] == self.current_room or item['location'] == 'inventory':
                    return f'{item["name"]}: {item["description"]}'
        return f'There is no {target} here to look at.'

    def save_game(self, filename: str) -> str:
        """Save game state to a JSON file."""
        game_state = {
            'current_room': self.current_room,
            'inventory': self.inventory,
            'items': self.items
        }
        try:
            with open(filename, 'w') as f:
                json.dump(game_state, f, indent=4)
            return f'Game saved to {filename}.'
        except Exception as e:
            return f'Failed to save game: {e}'

    def load_game(self, filename: str) -> str:
        """Load game state from a JSON file."""
        try:
            with open(filename, 'r') as f:
                game_state = json.load(f)
            self.current_room = game_state['current_room']
            self.inventory = game_state['inventory']
            self.items = game_state['items']
            return f'Game loaded from {filename}.\n' + self.describe_current_room()
        except Exception as e:
            return f'Failed to load game: {e}'

    def parse_command(self, command: str) -> str:
        """Parse and execute a two-word command."""
        words = command.strip().lower().split()
        if len(words) == 0:
            return 'Enter a command.'
        elif len(words) == 1:
            verb = words[0]
            if verb == 'look':
                return self.look()
            elif verb == 'inventory':
                return self.inventory_list()
            else:
                return f'Do what? ({verb})'
        else:
            verb, noun = words[0], ' '.join(words[1:])
            if verb == 'go':
                return self.move(noun)
            elif verb == 'get':
                return self.get_item(noun)
            elif verb == 'drop':
                return self.drop_item(noun)
            elif verb == 'look':
                return self.look(noun)
            elif verb == 'save':
                filename = noun if noun else 'savegame.json'
                return self.save_game(filename)
            elif verb == 'load':
                filename = noun if noun else 'savegame.json'
                return self.load_game(filename)
            else:
                return f'I do not understand the command "{verb} {noun}".'


if __name__ == '__main__':
    game = AdventureGame('config.json')
    print('Welcome to the Text Adventure! Type commands, or "quit" to exit.')
    print(game.describe_current_room())
    while True:
        command = input('> ')
        if command.lower() in ['quit', 'exit']:
            print('Goodbye!')
            break
        output = game.parse_command(command)
        print(output)
EOF

